    return f'<article class="lab-card"><div class="card-meta"><span>0{number} / {e(status)}</span><span>RESEARCH ARTEFACT</span></div><h3>{e(title)}</h3>' + (f'<p class="serif">{e(question)}</p>' if full else '') + f'<p>{e(body)}</p><p class="tech">{e(tech)}</p></article>'

